// MyReadingStatistics returns statistics for the authenticated user's library.
func (r *queryResolver) MyReadingStatistics(ctx context.Context) (*model.ReadingStatistics, error) {
	userID, err := authenticatedUserID(ctx)
	if err != nil {
		return nil, err
	}
	books := r.DB.Collection("books")
	stats := &model.ReadingStatistics{}
	base := bson.M{"userId": userID}
	stats.TotalCompletedBooks, err = countBooks(ctx, books, bson.M{"userId": userID, "status": string(model.BookStatusCompleted)})
	if err != nil {
		return nil, err
	}
	stats.CurrentlyReading, err = countBooks(ctx, books, bson.M{"userId": userID, "status": string(model.BookStatusReading)})
	if err != nil {
		return nil, err
	}
	stats.WantToRead, err = countBooks(ctx, books, bson.M{"userId": userID, "status": string(model.BookStatusWantToRead)})
	if err != nil {
		return nil, err
	}
	_ = base
	now := time.Now().UTC()
	start := time.Date(now.Year(), 1, 1, 0, 0, 0, 0, time.UTC)
	stats.CompletedThisYear, err = countBooks(ctx, books, bson.M{"userId": userID, "status": string(model.BookStatusCompleted), "completedAt": bson.M{"$gte": start}})
	if err != nil {
		return nil, err
	}
	var user UserDocument
	if err := r.DB.Collection("users").FindOne(ctx, bson.M{"_id": userID}).Decode(&user); err != nil {
		return nil, err
	}
	stats.YearlyReadingGoal = user.YearlyReadingGoal
	if stats.YearlyReadingGoal > 0 {
		stats.YearlyGoalProgress = float64(stats.CompletedThisYear) / float64(stats.YearlyReadingGoal) * 100
	}
	pipeline := mongo.Pipeline{
		{{Key: "$match", Value: bson.M{"userId": userID, "status": string(model.BookStatusReading), "pageCount": bson.M{"$gt": 0}}}},
		{{Key: "$project", Value: bson.M{"pct": bson.M{"$multiply": []any{bson.M{"$divide": []any{bson.M{"$ifNull": []any{"$currentPage", 0}}, "$pageCount"}}, 100}}}}},
		{{Key: "$group", Value: bson.M{"_id": nil, "average": bson.M{"$avg": "$pct"}}}},
	}
	cur, err := books.Aggregate(ctx, pipeline)
	if err != nil {
		return nil, err
	}
	defer cur.Close(ctx)
	var rows []struct {
		Average float64 `bson:"average"`
	}
	if err := cur.All(ctx, &rows); err != nil {
		return nil, err
	}
	if len(rows) > 0 {
		stats.ReadingProgress = rows[0].Average
	}
	return stats, nil
}

