// SearchBooks is the resolver for the searchBooks field.
func (r *queryResolver) SearchBooks(ctx context.Context, search string) ([]*model.Book, error) {
	search = strings.TrimSpace(search)
	if search == "" {
		return r.findBooks(ctx, bson.M{})
	}
	pattern := bson.M{"$regex": regexp.QuoteMeta(search), "$options": "i"}
	return r.findBooks(ctx, bson.M{"$or": []bson.M{{"title": pattern}, {"author": pattern}}})
}

